"""Fetch the UEA/UCR problem needed for C1 into ``data/<problem>/``.

Order of preference:
  1. already-present ``.ts`` files under data/<problem>/
  2. the shared download cache in $REPRO_DATA_CACHE/uea_ucr
  3. download the problem zip from timeseriesclassification.com (aeon-toolkit mirror)
"""

from __future__ import annotations

import io
import os
import shutil
import sys
import zipfile

import config

if os.path.isdir(os.path.join(config.DATA_DIR, config.DATASET)):
    sys.path.insert(0, config.DATA_DIR)


def _required_paths(problem: str) -> list:
    return [
        os.path.join(config.DATA_DIR, problem, f"{problem}_TRAIN.ts"),
        os.path.join(config.DATA_DIR, problem, f"{problem}_TEST.ts"),
    ]


def _already_present(problem: str) -> bool:
    return all(os.path.isfile(p) for p in _required_paths(problem))


def _copy_from_cache(problem: str, log) -> bool:
    cache = config.CACHE_UEA_DIR
    if not cache or not os.path.isdir(cache):
        return False
    src = {
        f"{problem}_TRAIN.ts": os.path.join(cache, f"{problem}_TRAIN.ts"),
        f"{problem}_TEST.ts": os.path.join(cache, f"{problem}_TEST.ts"),
    }
    if not all(os.path.isfile(v) for v in src.values()):
        return False
    dst_dir = os.path.join(config.DATA_DIR, problem)
    os.makedirs(dst_dir, exist_ok=True)
    for name, path in src.items():
        dst = os.path.join(dst_dir, name)
        shutil.copyfile(path, dst)
        log(f"  copied cached {name} ({os.path.getsize(dst)} bytes)")
    return True


def _download_zip(problem: str, log) -> bool:
    import requests  # local import so the module loads without network deps

    os.makedirs(config.DATA_DIR, exist_ok=True)
    for template in config.DATASET_ZIP_URLS:
        url = template.format(p=problem)
        log(f"  trying {url}")
        try:
            resp = requests.get(url, timeout=config.DOWNLOAD_TIMEOUT, stream=True)
        except Exception as exc:  # pragma: no cover - network dependent
            log(f"    failed: {exc}")
            continue
        if resp.status_code != 200:
            log(f"    HTTP {resp.status_code}")
            continue
        buf = io.BytesIO(resp.content)
        log(f"    downloaded {len(buf.getvalue())} bytes")
        try:
            with zipfile.ZipFile(buf) as zf:
                names = zf.namelist()
                log(f"    zip entries: {names}")
                zf.extractall(config.DATA_DIR)
        except Exception as exc:
            log(f"    unzip failed: {exc}")
            continue
        # Normalise: the archive may nest the files under <problem>/ (already fine)
        # or drop them straight into data/.
        nested = os.path.join(config.DATA_DIR, problem)
        if not os.path.isdir(nested):
            os.makedirs(nested, exist_ok=True)
        for name in names:
            base = os.path.basename(name)
            if base.endswith(".ts"):
                for cand in (os.path.join(config.DATA_DIR, base), os.path.join(nested, "data", base)):
                    if os.path.isfile(cand) and not os.path.isfile(os.path.join(nested, base)):
                        shutil.move(cand, os.path.join(nested, base))
        # Cache a copy for reuse by other runs.
        if config.CACHE_UEA_DIR:
            try:
                os.makedirs(config.CACHE_UEA_DIR, exist_ok=True)
                for p in _required_paths(problem):
                    if os.path.isfile(p):
                        tgt = os.path.join(config.CACHE_UEA_DIR, os.path.basename(p))
                        if not os.path.isfile(tgt):
                            shutil.copyfile(p, tgt)
            except OSError:
                pass
        return _already_present(problem)
    return False


def ensure_dataset(problem: str, log=print) -> str:
    """Make sure ``data/<problem>/<problem>_{TRAIN,TEST}.ts`` exist; return the source used."""
    if _already_present(problem):
        log(f"[data] {problem}: already present in data/, reusing")
        return "existing"
    log(f"[data] {problem}: not in data/, checking shared cache")
    if _copy_from_cache(problem, log) and _already_present(problem):
        log(f"[data] {problem}: restored from REPRO_DATA_CACHE")
        return "cache"
    log(f"[data] {problem}: cache miss, downloading from timeseriesclassification.com")
    if _download_zip(problem, log) and _already_present(problem):
        log(f"[data] {problem}: downloaded")
        return "download"
    raise RuntimeError(
        f"Could not obtain {problem} data (no local files, no cache entry, download failed)."
    )


if __name__ == "__main__":
    src = ensure_dataset(config.DATASET)
    print("source:", src)
    for p in _required_paths(config.DATASET):
        print(p, os.path.isfile(p), os.path.getsize(p) if os.path.isfile(p) else "-")

