def _gather_pool_features(F_pool, y_pool, Xtr, Xte, ytr, yte):
    """Map resampled raw series back onto pooled FTM rows by exact row matching."""
    keys = {}
    for i, row in enumerate(F_pool):
        keys.setdefault((round(row[0], 12), round(row[1], 12), str(y_pool[i])), []).append(i)

    def take(X, y):
        out, used = [], set()
        for feat, lab in zip(extract_ftm(X), y):
            k = (round(feat[0], 12), round(feat[1], 12), str(lab))
            pool = [i for i in keys.get(k, []) if i not in used]
            if not pool:
                raise KeyError(f"resampled series not found in pool: {k}")
            used.add(pool[0])
            out.append(pool[0])
        return F_pool[np.asarray(out, dtype=int)]

    return take(Xtr, ytr), take(Xte, yte)

